 if(saveRuntime.idleHandle!=null){if(typeof cancelIdleCallback==="function")cancelIdleCallback(saveRuntime.idleHandle);else clearTimeout(saveRuntime.idleHandle);saveRuntime.idleHandle=null;}
 saveRuntime.dirty=false;saveRuntime.pendingReason=null;
