function saveContinuitySnapshot(s){
 if(!s)return null;
 const ids=rows=>(Array.isArray(rows)?rows:[]).map(x=>String(x?.id||"")).filter(Boolean).sort(),owned=(Array.isArray(s.industry)?s.industry:[]).filter(x=>x?.acquired||String(x?.status||"")==="merged_into_player").map(x=>String(x.id||"")+"|"+String(x.status||"")+"|"+(x.acquired?"1":"0")).sort(),factoryIds=Array.isArray(s.operations?.factories)?ids(s.operations.factories):[];
 return{campaignId:s.campaignId||null,company:String(s.company||""),year:Number(s.year||0),month:Number(s.month||0),day:Number(s.day||0),daysPlayed:Number(s.daysPlayed||0),monthsPlayed:Number(s.monthsPlayed||0),cash:Number(s.cash),debt:Number(s.debt||0),vehicleIds:ids(s.vehicles),engineIds:ids(s.engines),transmissionIds:ids(s.transmissions),subsidiaryIds:ids(s.subsidiaries),ownedIndustry:owned,factoryIds,factoryCount:Number(s.factories||factoryIds.length||0),pendingDealIds:ids(s.pendingDeals),integrationIds:ids(s.integrations)};
}
function assertSaveContinuity(before,after,strictAssets=false){
 if(!before||!after)return true;const failures=[];
 if(before.campaignId&&after.campaignId&&before.campaignId!==after.campaignId)failures.push("campaign id changed");
 if(before.company&&after.company&&before.company!==after.company)failures.push("company changed");
 if(before.year&&after.year&&before.year!==after.year)failures.push("year changed");
 if(Number.isFinite(before.month)&&Number.isFinite(after.month)&&before.month!==after.month)failures.push("month changed");
 if(before.day&&after.day&&before.day!==after.day)failures.push("day changed");
 if(before.daysPlayed>0&&after.daysPlayed<before.daysPlayed)failures.push("days played moved backward");
 if(before.monthsPlayed>0&&after.monthsPlayed<before.monthsPlayed)failures.push("months played moved backward");
 if(strictAssets){
  const same=(a,b)=>JSON.stringify(a||[])===JSON.stringify(b||[]);
  if(Number.isFinite(before.cash)&&Number.isFinite(after.cash)&&Math.abs(before.cash-after.cash)>.001)failures.push("cash changed during reputation migration");
  if(Number.isFinite(before.debt)&&Number.isFinite(after.debt)&&Math.abs(before.debt-after.debt)>.001)failures.push("debt changed during reputation migration");
  if(!same(before.vehicleIds,after.vehicleIds))failures.push("vehicle roster changed during reputation migration");
  if(!same(before.engineIds,after.engineIds))failures.push("engine roster changed during reputation migration");
  if(!same(before.transmissionIds,after.transmissionIds))failures.push("transmission roster changed during reputation migration");
  if(!same(before.subsidiaryIds,after.subsidiaryIds))failures.push("subsidiary roster changed during reputation migration");
  if(!same(before.ownedIndustry,after.ownedIndustry))failures.push("owned / merged company state changed during reputation migration");
  if(!same(before.factoryIds,after.factoryIds)||before.factoryCount!==after.factoryCount)failures.push("factory state changed during reputation migration");
  if(!same(before.pendingDealIds,after.pendingDealIds))failures.push("pending deals changed during reputation migration");
  if(!same(before.integrationIds,after.integrationIds))failures.push("integration queue changed during reputation migration");
 }
 if(failures.length)throw new Error("Save continuity guard blocked update: "+failures.join(", "));
 return true;
}
