const activitySyncCache=new Map();
function activityFollowUiAvailable(){return !!(window.MDXNative?.isNativeApp||window.MDXAppReadiness?.developer?.enabled);}
function activityFollowKey(source,id){return String(source||"program")+":"+String(id||"");}
function isProgramActivityFollowed(source,id){return (state?.appActivityFollows||[]).some(x=>x.source===source&&x.id===id);}
function programActivityPayload(source,id,pOverride=null){
 const p=pOverride||liveProgramTiming(source,id);if(!p)return null;const total=Math.max(1,Number(p.totalDays||1)),remaining=Math.max(0,Number(p.daysRemaining||0)),progress=clamp(1-remaining/total,0,1),title=p.name||p.platform?.name||(source==="preprod"?state.vehicles.find(x=>x.id===id)?.name:null)||"Motor Dynasty Project",phase=p.userPaused?"Paused by management":String(p.phase||"Development").replaceAll("_"," "),type=source==="engine"||source==="engineRevision"?"engine_program":source==="vehicle"||source==="preprod"||source==="model"?"vehicle_program":source==="transmission"?"transmission_program":source==="platform"?"platform_program":source==="test"?"validation_program":"development_program";
 return{activityId:"program:"+activityFollowKey(source,id),type,title,subtitle:phase+" • "+Math.ceil(remaining)+" in-game days remaining",progress,status:p.status==="active"?(p.userPaused?"paused":"active"):String(p.status||"complete"),deepLink:window.MDXRouter?.build?.("program",id,{source})||"#/program/"+encodeURIComponent(id),relatedObjectIds:[id],programSource:source,programId:id};
}
function syncFollowedActivities(force=false){
 if(!state||!window.MDXNative)return false;state.appActivityFollows=Array.isArray(state.appActivityFollows)?state.appActivityFollows:[];let changed=false;
 for(const f of [...state.appActivityFollows]){const key=activityFollowKey(f.source,f.id),p=liveProgramTiming(f.source,f.id),payload=programActivityPayload(f.source,f.id,p);
  if(!p||!payload||payload.status==="complete"||payload.status==="released"||payload.status==="cancelled"||payload.progress>=1){window.MDXNative.endLiveActivity?.("program:"+key);activitySyncCache.delete(key);state.appActivityFollows=state.appActivityFollows.filter(x=>activityFollowKey(x.source,x.id)!==key);changed=true;continue;}
  const sig=[Math.floor(payload.progress*10),payload.subtitle,payload.status].join("|"),prior=activitySyncCache.get(key);if(force||prior!==sig){if(prior==null)window.MDXNative.startLiveActivity?.(payload);else window.MDXNative.updateLiveActivity?.(payload);activitySyncCache.set(key,sig);}
 }
 return changed;
}
function toggleProgramActivityFollow(source,id){
 if(!activityFollowUiAvailable())return false;state.appActivityFollows=Array.isArray(state.appActivityFollows)?state.appActivityFollows:[];const key=activityFollowKey(source,id),exists=isProgramActivityFollowed(source,id);
 if(exists){state.appActivityFollows=state.appActivityFollows.filter(x=>activityFollowKey(x.source,x.id)!==key);window.MDXNative?.endLiveActivity?.("program:"+key);activitySyncCache.delete(key);haptic("confirmationLight");showToast("Project Live Activity stopped");}
 else{const payload=programActivityPayload(source,id);if(!payload)return false;state.appActivityFollows.push({source,id});window.MDXNative?.startLiveActivity?.(payload);activitySyncCache.set(key,[Math.floor(payload.progress*10),payload.subtitle,payload.status].join("|"));haptic("confirmationLight");showToast("Following "+payload.title+" in Live Activity");}
 saveGame();return true;
}
