function subsidiaryManagerSectionPane(section){
 const eyebrow=String(section?.querySelector(".eyebrow")?.textContent||"").trim().toUpperCase();
 if(["SUBSIDIARY BOARD REQUEST","TURNAROUND FUNDING GAP","PARENT POLICY","OPERATING ALLOCATION"].some(x=>eyebrow.includes(x)))return"financials";
 if(["PRODUCTION HELP REQUEST","POWERTRAIN CONTRACT POLICY"].some(x=>eyebrow.includes(x)))return"operations";
 if(eyebrow.includes("OPERATING COMPANY"))return"products";
 if(["TURNAROUND COMMAND","OWNER MANDATE"].some(x=>eyebrow.includes(x)))return"strategy";
 if(["MANAGEMENT AI","GROUP STRUCTURE"].some(x=>eyebrow.includes(x)))return"history";
 return"overview";
}
function subsidiaryManagerDashboardHtml(s,m,cars,projects,control){
 const revenue=Number(s.lastRevenue||0),profit=Number(s.lastProfit||0),value=Math.max(1,Number(s.value||m?.valuation||1)),cash=Number(s.cash||m?.cash||0),debt=Number(s.debt||m?.debt||0),margin=revenue?profit/revenue*100:0,debtPct=debt/value*100,util=Number(s.factoryUtilization||m?.factoryUtilization||0)*100,production=Math.max(0,Number(s.lastProduction||0)),sales=Math.max(0,Number(s.lastSales||0)),inventory=Math.max(0,Number(s.lastInventory||0)),sellThrough=production?sales/production*100:(sales>0?100:0),inventoryDays=sales>0?inventory/sales*30:(inventory>0?999:0),pending=(s.parentCapitalRequest?1:0)+(s.productionHelpRequest?.status==="pending"?1:0)+(String(m?.status||"active")==="distressed"||String(m?.status||"active")==="restructuring"?1:0),tab=subsidiaryManagerTab;
 const title={overview:"Owner Dashboard",financials:"Treasury & Capital",operations:"Operating Controls",products:"Products & Inventory",strategy:"Mandate & Turnaround",history:"Company Record"}[tab]||"Owner Dashboard";
 const subtitle={overview:"A fast read on the subsidiary before you change anything.",financials:"Understand exactly how parent cash, profit sweeps and budgets interact.",operations:"Control sourcing, contract sales and operating authority without micromanaging every decision.",products:"See whether production is matching demand and where inventory is building.",strategy:"Set the long-term direction while the subsidiary keeps its own identity and management simulation.",history:"Review management decisions and decide whether the company stays separate or merges into the parent."}[tab]||"";
 const metrics={
  overview:[["OPERATING MARGIN",(margin>=0?"+":"")+margin.toFixed(1)+"%",margin>=0?"positive":"negative"],["DEBT / VALUE",debtPct.toFixed(1)+"%",debtPct>65?"negative":""],["FACTORY UTIL.",Math.round(util)+"%",util>92?"negative":util>82?"warning":""],["OPEN ATTENTION",String(pending),pending?"warning":"positive"],["PHYSICAL SCALE",String(s.operatingVolumeClass||m?.operatingVolumeClass||"—").toUpperCase(),""],["COMMERCIAL SCALE",String(s.commercialVolumeClass||m?.commercialVolumeClass||s.operatingVolumeClass||"—").toUpperCase(),""],["PARENT-BACKED AGE",Number(s.casualParentBackingMonths||m?.casualParentBackingMonths||0)+" MO",""],["ACTIVE MODELS",String(cars.length),""]],
  financials:[["COMPANY CASH",money(cash),cash<0?"negative":""],["LAST NET PROFIT",money(profit),profit>=0?"positive":"negative"],["PROFIT SWEEP",Math.round(Number(s.profitSweepPct??50))+"%",""],["PARENT SUPPORT CAP",money(s.parentSupportMonthly||0)+"/mo",""]],
  operations:[["FACTORY UTIL.",Math.round(util)+"%",util>92?"negative":""],["DEALER HEALTH",Math.round(Number(s.dealerHealth||0))+"/100",Number(s.dealerHealth||0)<55?"negative":""],["FACTORIES",Number(s.factories||0).toLocaleString(),""],["DEALERS",Number(s.dealers||0).toLocaleString(),""]],
  products:[["ACTIVE MODELS",String(cars.length),""],["IN DEVELOPMENT",String(projects.length),""],["SELL-THROUGH",sellThrough.toFixed(0)+"%",sellThrough<65?"negative":sellThrough>90?"positive":""],["INVENTORY DAYS",inventoryDays>=999?"NO SALES":Math.round(inventoryDays)+" DAYS",inventoryDays>90?"negative":""]],
  strategy:[["PRODUCT MANDATE",String(s.productMandate||"heritage").replaceAll("_"," ").toUpperCase(),""],["BUSINESS MODEL",String(s.operatingModel||"balanced").replaceAll("_"," ").toUpperCase(),""],["AUTONOMY",String(s.autonomy||"high").toUpperCase(),""],["BUDGET MODE",control==="manual"?"PARENT DIRECTED":"MANAGEMENT AI",""]],
  history:[["YEARS OWNED",subsidiaryYearsHeld(s).toFixed(1),""],["AI DECISIONS",String((m?.aiDecisionLog||s.aiDecisionLog||[]).length),""],["PARENT CAPITAL",money(s.parentCapitalInjected||0),""],["MERGER STATUS",String(s.mergeStatus||"SEPARATE").replaceAll("_"," ").toUpperCase(),""]]
 }[tab]||[];
 const guides={
  overview:[["USE THE TABS","Financials controls cash. Operations controls sourcing. Products shows the live lineup. Strategy changes where management takes the company."],["GROWTH PACING","Physical plants and commercial reach are tracked separately. Parent backing prevents a Casual-mode collapse, but new factories, dealers and product lines now require time, demand and funded investment."],["WATCH INVENTORY","High production with weak sell-through creates cash tied up in unsold vehicles. Products makes that visible without digging through the whole company."],["ATTENTION COUNT","This flags pending parent requests or operating distress. It is a navigation aid, not a hidden penalty."]],
  financials:[["PROFIT SWEEP","The selected percentage of positive subsidiary net profit can move to parent cash at month close, but only when the subsidiary has enough cash above its operating reserve."],["CAPITAL SUPPORT LIMIT","This caps automatic parent support when subsidiary cash falls below its operating reserve. Setting it to $0 stops automatic support; manual injections still work."],["BUDGET AUTHORITY","Management AI can rebalance spending as conditions change. Parent Directed locks the monthly R&D, quality, marketing, dealer, admin and capex allocations you set."],["INJECT CAPITAL","Moves real parent cash into this company immediately. It raises subsidiary liquidity; it is not revenue or free money."]],
  operations:[["CONTRACT SALES","ALLOW lets management accept suitable engine or transmission supply business. SELL AGGRESSIVELY tells it to actively pursue those customers. OFF stops new sales contracts."],["OUTSIDE SOURCING","BLOCK NEW prevents additional outside engine or transmission purchase contracts. Existing signed agreements continue until they expire."],["OPERATING AUTONOMY","Autonomy controls how freely subsidiary management acts inside your mandate. It does not change your ownership percentage."],["PRODUCTION HELP","When the subsidiary is capacity-constrained it can request overflow assembly from the parent. Approved work uses real intercompany manufacturing terms."]],
  products:[["SELL-THROUGH","Compares the last month sold with the last month built. A low number is a warning that production is running ahead of demand."],["INVENTORY DAYS","Approximate inventory divided by the last sales pace. Very high days means cash is sitting in unsold stock."],["ACTIVE PROGRAMS","Development programs remain run by the subsidiary AI unless your broader strategy or turnaround actions change its priorities."]],
  strategy:[["PRODUCT POSITION","Preserve protects the brand’s historic position. Value, Premium and Performance gradually bias future products, pricing and engineering choices."],["BUSINESS MODEL","Lean protects cash, Volume pushes scale, Growth favors expansion, and Balanced avoids an extreme bias."],["TURNAROUND ACTIONS","Recovery actions spend real cash and change specific operating conditions. They are tracked with cooldowns and a permanent decision log."]],
  history:[["MANAGEMENT DECISIONS","The company posts the reasons behind recent AI actions so you can see why it changed spending, products, production or commercial behavior."],["KEEP SEPARATE","The company keeps its own cash, debt, factories, products, dealers and AI decisions."],["MERGE INTO PARENT","A merger absorbs eligible assets into the parent and ends the subsidiary as an independently simulated company. Public subsidiaries must be taken private first."]]
 }[tab]||[];
 return"<section class='company-manager-dashboard'><div class='company-manager-dashboard-head'><div><span class='eyebrow'>"+title.toUpperCase()+"</span><h3>"+title+"</h3><p>"+subtitle+"</p></div>"+(pending&&tab==="overview"?"<span class='manager-signal warning'>"+pending+" NEED"+(pending===1?"S":"")+" ATTENTION</span>":"<span class='manager-signal'>LIVE COMPANY DATA</span>")+"</div><div class='company-manager-health-grid'>"+metrics.map(x=>"<div class='company-manager-health-card "+(x[2]||"")+"'><span>"+x[0]+"</span><b>"+x[1]+"</b></div>").join("")+"</div><div class='company-control-guide'>"+guides.map(x=>"<article class='company-control-card'><b>"+x[0]+"</b><p>"+x[1]+"</p></article>").join("")+"</div></section>";
}
