function industrialManagerDashboardHtml(c,reserve,excessCash,ttmRevenue,ttmProfit,policy){
 const tab=industrialManagerTab,value=Math.max(1,Number(c.value||1)),debt=Math.max(0,Number(c.debt||0)),cash=Number(c.cash||0),margin=ttmRevenue?ttmProfit/ttmRevenue*100:0,debtPct=debt/value*100,util=Number(c.utilization||0)*100,units=Math.max(0,Number(c.monthUnits||0)),capacity=Math.max(0,Number(c.capacity||0)),headroom=Math.max(0,capacity-units),contracts=(c.contracts||[]).filter(x=>!["complete","expired","cancelled"].includes(String(x.status||"").toLowerCase())).length,third=Number(c.monthThirdPartyRevenue||0),inter=Number(c.monthIntercompanySales||0),commercial=Math.max(0,third+inter),thirdMix=commercial>0?third/commercial*100:0,rd=Number(c.monthRd||c.rdBudget||0),rdPct=Number(c.revenue||0)>0?rd/Number(c.revenue||1)*100:0,safeRepay=Math.max(0,Math.min(debt,excessCash)),reserveShortfall=Math.max(0,reserve-cash),policyPctMap={retain:0,"25":25,"50":50,"75":75,max:90,growth:25,debt:15},distPct=policyPctMap[policy]??Number(policy||0);
 const title={overview:"Company Health",financials:"Treasury Control",operations:"Capacity & Workforce",contracts:"Commercial Book",strategy:"R&D & Operating Strategy",history:"Decision Record"}[tab]||"Company Health";
 const subtitle={overview:"See the operating company as an owner, not just a row of raw numbers.",financials:"Every cash action below moves real company or parent cash and respects the operating reserve.",operations:"Headcount and plant capacity determine how much demand this company can actually serve.",contracts:"Separate outside customer business from internal group demand and see what the supplier is selling.",strategy:"Direct the company’s investment posture while keeping the industrial simulation autonomous.",history:"A permanent record of acquisitions, owner directives and management decisions."}[tab]||"";
 const metrics={
  overview:[["TTM MARGIN",(margin>=0?"+":"")+margin.toFixed(1)+"%",margin>=0?"positive":"negative"],["DEBT / VALUE",debtPct.toFixed(1)+"%",debtPct>60?"negative":""],["CASH ABOVE RESERVE",money(excessCash),excessCash>0?"positive":""],["SUPPLIER SHARE",Number(c.marketShare||0).toFixed(1)+"%",""]],
  financials:[["COMPANY CASH",money(cash),cash<reserve?"warning":""],["PROTECTED RESERVE",money(reserve),""],["EXCESS CASH",money(excessCash),excessCash>0?"positive":""],["DISTRIBUTION TARGET",distPct+"%",""],["TTM NET PROFIT",money(ttmProfit),ttmProfit>=0?"positive":"negative"],["DEBT / VALUE",debtPct.toFixed(1)+"%",debtPct>60?"negative":""]],
  operations:[["UTILIZATION",Math.round(util)+"%",util>92?"negative":util>82?"warning":""],["MONTH OUTPUT",units.toLocaleString(),""],["CAPACITY HEADROOM",headroom.toLocaleString()+"/mo",headroom<capacity*.08?"warning":""],["WORKFORCE FACTOR",Math.round(Number(c.monthWorkforceFactor??1)*100)+"%",""]],
  contracts:[["THIRD-PARTY CUSTOMERS",Number(c.customers||0).toLocaleString(),""],["ACTIVE CONTRACTS",String(contracts),""],["THIRD-PARTY SALES",money(third),""],["INTERCOMPANY SALES",money(inter),""],["OUTSIDE SALES MIX",thirdMix.toFixed(0)+"%",""]],
  strategy:[["CURRENT STRATEGY",String(c.managementStrategy||"balanced").toUpperCase(),""],["R&D / MONTH",money(rd),""],["R&D / REVENUE",rdPct.toFixed(1)+"%",""],["QUALITY",Math.round(Number(c.quality||0))+"/100",""],["RELIABILITY",Math.round(Number(c.reliability||0))+"/100",""]],
  history:[["OWNER EVENTS",String((c.acquisitionHistory||[]).length),""],["MANAGEMENT EVENTS",String((c.decisionHistory||[]).length),""],["LIFETIME REVENUE",money(c.lifetimeRevenue||0),""],["LIFETIME PROFIT",money(c.lifetimeProfit||0),Number(c.lifetimeProfit||0)>=0?"positive":"negative"]]
 }[tab]||[];
 const guides={
  overview:[["CASH VS. VALUE","Company value is not spendable cash. Cash funds payroll, R&D, capex and debt service; valuation reflects the operating business."],["UTILIZATION","High utilization means the plants are busy. Near-full utilization can cap sales until you add capacity or improve the workforce."],["QUALITY + RELIABILITY","These influence product competitiveness and the long-run strength of the supplier. R&D and strategy can improve them over time."]],
  financials:[["RETAIN ALL","Pays 0% of eligible monthly profit to the parent, leaving the most cash inside the company."],["25 / 50 / 75%","Targets that share of positive eligible profit for the parent. The actual payment can be reduced or skipped to protect the operating reserve."],["MAX SUSTAINABLE","Targets 90% of eligible profit, still limited by real cash and the protected reserve."],["GROWTH","Targets a 25% distribution so more earnings remain available for expansion and operating investment."],["DEBT REDUCTION","Targets only a 15% distribution so more cash stays inside the company for liabilities. Use the debt buttons to make an actual principal repayment."],["INJECT / SWEEP","Inject moves parent cash into the company. Sweep moves only cash above the protected reserve back to the parent. Neither action creates revenue."]],
  operations:[["TARGET HEADCOUNT","Sets the workforce level management moves toward. Hiring and layoffs phase in and carry real adjustment costs."],["BUILD / EXPAND FACTORY","Uses company cash for capex, adds a factory and increases capacity. Expansion is blocked while a recent capacity program is still ramping."],["CAPACITY HEADROOM","The gap between current monthly output and installed capacity. Very little headroom means new demand may require expansion."]],
  contracts:[["THIRD-PARTY SALES","Revenue earned from customers outside your corporate group."],["INTERCOMPANY SALES","Supply sold to your parent or other group operations. It is tracked separately so consolidated reporting can eliminate internal revenue correctly."],["ACTIVE CONTRACTS","Named supply agreements appear here when the contract economy creates them; the broader customer count also includes regular operating demand."]],
  strategy:[["LEAN","Biases the company toward cost control and liquidity protection."],["BALANCED","Keeps investment, quality and growth priorities near the middle."],["GROWTH","Favors capacity and customer expansion when liquidity can support it."],["TECHNOLOGY","Favors R&D and future product capability, especially in technology-heavy industries."],["QUALITY","Prioritizes process, quality and reliability improvement."],["R&D BUDGET","Sets the monthly industrial engineering target. Actual spend is reported separately so you can see whether the company could fund the plan."]],
  history:[["DECISION LOG","Owner directives and management decisions remain attached to this company so you can see how it evolved after acquisition."],["DISTRIBUTION HISTORY","Financials records actual paid or skipped distributions, including the reason reserve constraints reduced a payment."]]
 }[tab]||[];
 const quick=tab==="financials"?"<div class='company-manager-quick-actions'>"+(reserveShortfall>0?"<button class='btn hero' data-industrial-fill-reserve='"+Math.ceil(reserveShortfall)+"'>FUND TO RESERVE • "+money(reserveShortfall)+"</button>":"")+(safeRepay>0?"<button class='btn secondary' data-industrial-repay-excess='"+Math.floor(safeRepay)+"'>REPAY DEBT FROM EXCESS • "+money(safeRepay)+"</button>":"")+"</div>":"";
 return"<section class='company-manager-dashboard industrial-manager-dashboard'><div class='company-manager-dashboard-head'><div><span class='eyebrow'>OWNER DETAIL</span><h3>"+title+"</h3><p>"+subtitle+"</p></div><span class='manager-signal'>"+String(c.status||"active").replaceAll("_"," ").toUpperCase()+"</span></div><div class='company-manager-health-grid'>"+metrics.map(x=>"<div class='company-manager-health-card "+(x[2]||"")+"'><span>"+x[0]+"</span><b>"+x[1]+"</b></div>").join("")+"</div>"+quick+"<div class='company-control-guide'>"+guides.map(x=>"<article class='company-control-card'><b>"+x[0]+"</b><p>"+x[1]+"</p></article>").join("")+"</div></section>";
}
