 const p=state.ipoProcess,u=ipoUnderwriter(p.underwriter),pr=ipoPricing(p.pricing),demand=clamp(.72+companyReputationValue()/220+(trailingProfit()>0?.15:-.08)+u.demand+pr.demand,.65,1.28),preMoney=state.valuation*pr.multiple*demand,preShares=state.sharesOutstanding,price=preMoney/preShares,newShares=preShares*(p.floatPct/(100-p.floatPct)),gross=newShares*price,fees=gross*u.fee,net=Math.max(0,gross-fees);
