function drawDyno(){const e=calcEngine(),c=$("dynoCanvas"),ctx=c.getContext("2d"),W=c.width,H=c.height,pad=58;ctx.clearRect(0,0,W,H);ctx.fillStyle="#060b10";ctx.fillRect(0,0,W,H);ctx.strokeStyle="#1f2c38";for(let i=0;i<=5;i++){let y=pad+i*(H-pad*2)/5;ctx.beginPath();ctx.moveTo(pad,y);ctx.lineTo(W-pad,y);ctx.stroke();}let hpP=[],tqP=[],max=1;for(let i=0;i<=70;i++){const rpm=800+(eng.redline-800)*i/70,peak=eng.redline*(eng.aspiration==="turbo"?.52:eng.aspiration==="supercharged"?.48:.61),spread=eng.redline*.39;let tq=e.tq*(.51+.51*Math.exp(-Math.pow((rpm-peak)/spread,2)));if(eng.aspiration==="turbo")tq*=clamp(.25+(rpm-(1850+Math.max(0,eng.boost-8)*55))/1500,.25,1);const hp=tq*rpm/5252;hpP.push([rpm,hp]);tqP.push([rpm,tq]);max=Math.max(max,hp,tq);}function line(p,col){ctx.strokeStyle=col;ctx.lineWidth=4;ctx.beginPath();p.forEach((a,i)=>{const x=pad+(W-2*pad)*(a[0]-800)/(eng.redline-800),y=H-pad-(H-2*pad)*a[1]/(max*1.08);i?ctx.lineTo(x,y):ctx.moveTo(x,y)});ctx.stroke();}line(tqP,"#54a7da");line(hpP,"#e8a71a");ctx.fillStyle="#718292";ctx.font="16px Inter";ctx.fillText("800",pad-12,H-25);ctx.fillText(eng.redline+" RPM",W-pad-80,H-25);$("dynoSummary").innerHTML=[["PEAK POWER",Math.round(e.hp)+" hp"],["PEAK TORQUE",Math.round(e.tq)+" lb-ft"],["PISTON SPEED",e.pistonSpeed.toFixed(1)+" m/s"],["FAILURE RISK",Math.round(e.failureRisk)+"%"]].map(x=>"<div><span>"+x[0]+"</span><b>"+x[1]+"</b></div>").join("");}

